// Product name = Sub-category from the SKU master, never generated by the model.
// Master: sharepoint_to_gcp.Frido_Item_Master__frido_item_sku_master (Product_Code, Sub_category, Category_Name).
// Aliases: Frido_Item_Master__productid_sku_mapping (productid / sellerskucode -> masterskucode).
import { getBQ, guardSql } from './bigquery.js';

const TTL_MS = 60 * 60 * 1000;
let cache = null; // { at, master: Map(code -> {sub, cat}), alias: Map(code -> master code) }

async function load() {
  if (cache && Date.now() - cache.at < TTL_MS) return cache;
  const bq = getBQ();
  const q = async sql => {
    guardSql(sql);
    const [rows] = await bq.query({ query: sql, maximumBytesBilled: String(1024 ** 3) });
    return rows;
  };
  const masterRows = await q('SELECT Product_Code, Sub_category, Category_Name FROM `frido-429506.sharepoint_to_gcp.Frido_Item_Master__frido_item_sku_master`');
  const aliasRows = await q('SELECT productid, sellerskucode, masterskucode FROM `frido-429506.sharepoint_to_gcp.Frido_Item_Master__productid_sku_mapping`');
  const master = new Map();
  for (const r of masterRows) {
    if (r.Product_Code) master.set(clean(r.Product_Code), { sub: r.Sub_category || '', cat: r.Category_Name || '' });
  }
  const alias = new Map();
  for (const r of aliasRows) {
    const m = r.masterskucode && clean(r.masterskucode);
    if (!m) continue;
    for (const k of [r.productid, r.sellerskucode]) if (k) alias.set(clean(k), clean(m));
  }
  cache = { at: Date.now(), master, alias };
  return cache;
}

const clean = x => String(x).toUpperCase().replace(/[^A-Z0-9-]/g, '');
const SKU_HEADER = /^(sku|masterskucode|master_sku|item_sku_code|itemskucode|final_sku|sku_code|product_code|channelskucode)$/i;

function lookup(c, code) {
  // Try the code as given, then without a _RAW / _PO24 pack suffix, then its first "_" segment.
  const raw = String(code).trim().toUpperCase();
  for (const t of [raw, raw.replace(/(_RAW)?(_PO\d+)?$/, ''), raw.split('_')[0]]) {
    const key = clean(t);
    const hit = c.master.get(key) || (c.alias.has(key) ? c.master.get(c.alias.get(key)) : null);
    if (hit) return hit;
  }
  return null;
}

// Appends Sub_Category and Category columns after any result that has a SKU column.
// Returns { text, skus: Map(sku -> sub-category or null) }.
export async function enrichSkus(text) {
  const lines = String(text).split('\n');
  const headers = (lines[0] || '').split('\t');
  const idx = headers.findIndex(h => SKU_HEADER.test(h.trim()));
  if (idx < 0 || headers.some(h => /^sub_?category/i.test(h.trim()))) return { text, skus: new Map() };
  let c;
  try { c = await load(); } catch { return { text, skus: new Map() }; }
  const skus = new Map();
  const out = [lines[0] + '\tSub_Category (product name)\tCategory'];
  for (let i = 1; i < lines.length; i++) {
    const cells = lines[i].split('\t');
    if (cells.length !== headers.length) { out.push(lines[i]); continue; }
    const raw = cells[idx];
    if (!raw || raw === 'NULL') { out.push(lines[i] + '\tnot in SKU master\tnot in SKU master'); continue; }
    const hit = lookup(c, raw);
    skus.set(raw, hit && hit.sub ? hit.sub : null);
    out.push(lines[i] + '\t' + (hit && hit.sub ? hit.sub : 'not in SKU master') + '\t' + (hit && hit.cat ? hit.cat : 'not in SKU master'));
  }
  return { text: out.join('\n'), skus };
}

// Markdown rows that contain a known SKU but not its master sub-category (a name the model made up).
export function wrongNames(answer, skus) {
  const bad = [];
  for (const row of String(answer).split('\n')) {
    if (!row.trim().startsWith('|')) continue;
    for (const [sku, sub] of skus) {
      if (!sku || !row.includes(sku)) continue;
      const want = sub || 'not in SKU master';
      if (!row.toLowerCase().includes(want.toLowerCase())) bad.push({ sku, want });
    }
  }
  return bad;
}
